470	fn rsplit_delimiter<'s, 'o>(
471	    value: Result<&'s str, &'o OsStr>,
472	    delimiter: Option<char>,
473	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
474	    let delimiter = delimiter?;
475	    let value = value.ok()?;
476	    let pos = value.rfind(delimiter)?;
477	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
478	    Some((Some(prefix), Ok(value)))
479	}
