481	fn complete_value_candidates(
482	    value: &OsStr,
483	    completer: &dyn ValueCandidates,
484	) -> Vec<CompletionCandidate> {
485	    debug!("complete_value_candidates: value={value:?}");
486	
487	    let mut values = completer.candidates();
488	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
489	    values
490	}
491	
492	fn complete_candidates_str(
493	    value: &str,
494	    mut values: Vec<CompletionCandidate>,
495	) -> Vec<CompletionCandidate> {
496	    debug!("complete_candidates_str: value={value:?}");
497	
498	    values.retain(|comp| comp.get_value().starts_with(value));
499	    values
500	}
501	
502	fn complete_value_candidates_str(
503	    value: &str,
504	    completer: &dyn ValueCandidates,
505	) -> Vec<CompletionCandidate> {
506	    debug!("complete_value_candidates_str: value={value:?}");
507	
508	    complete_candidates_str(value, completer.candidates())
509	}
