537	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
538	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
539	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
540	    debug!("longs: name={}", p.get_name());
541	
542	    p.get_arguments()
543	        .filter_map(|a| {
544	            a.get_long_and_visible_aliases().map(|longs| {
545	                longs
546	                    .into_iter()
547	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
548	            })
549	        })
550	        .flatten()
551	        .collect()
552	}
553	
554	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
555	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
556	    debug!("longs: name={}", p.get_name());
557	
558	    p.get_arguments()
559	        .filter_map(|a| {
560	            a.get_aliases().map(|longs| {
561	                longs.into_iter().map(|s| {
562	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
563	                })
564	            })
565	        })
566	        .flatten()
567	        .collect()
568	}
569	
570	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
571	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
572	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
573	    debug!("shorts: name={}", p.get_name());
574	
575	    p.get_arguments()
576	        .filter_map(|a| {
577	            a.get_short_and_visible_aliases().map(|shorts| {
578	                shorts.into_iter().map(|s| {
579	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
580	                        a.get_help()
581	                            .cloned()
582	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
583	                    )
584	                })
585	            })
586	        })
587	        .flatten()
588	        .collect()
589	}
590	
591	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
592	    candidate
593	        .help(arg.get_help().cloned())
594	        .id(Some(format!("arg::{}", arg.get_id())))
595	        .tag(Some(
596	            arg.get_help_heading()
597	                .unwrap_or("Options")
598	                .to_owned()
599	                .into(),
600	        ))
601	        .display_order(Some(arg.get_display_order()))
602	        .hide(arg.is_hide_set())
603	}
