605	/// Get the possible values for completion
606	fn possible_values(
607	    a: &clap::Arg,
608	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
609	    if !a.get_num_args().expect("built").takes_values() {
610	        None
611	    } else {
612	        a.get_value_parser().possible_values()
613	    }
614	}
615	
616	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
617	///
618	/// Subcommand `rustup toolchain install` would be converted to
619	/// `("install", "rustup toolchain install")`.
620	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
621	    debug!("subcommands: name={}", p.get_name());
622	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
623	    p.get_subcommands()
624	        .flat_map(|sc| {
625	            sc.get_name_and_visible_aliases()
626	                .into_iter()
627	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
628	                .chain(sc.get_aliases().map(|s| {
629	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
630	                        .hide(true)
631	                }))
632	        })
633	        .collect()
634	}
635	
636	fn populate_command_candidate(
637	    candidate: CompletionCandidate,
638	    cmd: &clap::Command,
639	    subcommand: &clap::Command,
640	) -> CompletionCandidate {
641	    candidate
642	        .help(subcommand.get_about().cloned())
643	        .id(Some(format!("command::{}", subcommand.get_name())))
644	        .tag(Some(
645	            cmd.get_subcommand_help_heading()
646	                .unwrap_or("Commands")
647	                .to_owned()
648	                .into(),
649	        ))
650	        .display_order(Some(subcommand.get_display_order()))
651	        .hide(subcommand.is_hide_set())
652	}
653	
654	/// Parse the short flags and find the first `takes_values` option.
655	fn parse_shortflags<'c, 's>(
656	    cmd: &'c clap::Command,
657	    mut short: clap_lex::ShortFlags<'s>,
658	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
659	    let takes_value_opt;
660	    let mut leading_flags = String::new();
661	    // Find the first takes_values option.
662	    loop {
663	        match short.next_flag() {
664	            Some(Ok(opt)) => {
665	                leading_flags.push(opt);
666	                let opt = cmd.get_arguments().find(|a| {
667	                    let shorts = a.get_short_and_visible_aliases();
668	                    let is_find = shorts.map(|v| {
669	                        let mut iter = v.into_iter();
670	                        let c = iter.find(|c| *c == opt);
671	                        c.is_some()
672	                    });
673	                    is_find.unwrap_or(false)
674	                });
675	                if opt
676	                    .map(|o| o.get_num_args().expect("built").takes_values())
677	                    .unwrap_or(false)
678	                {
679	                    takes_value_opt = opt;
680	                    break;
681	                }
682	            }
683	            Some(Err(_)) | None => {
684	                takes_value_opt = None;
685	                break;
686	            }
687	        }
688	    }
689	
690	    (leading_flags, takes_value_opt, short)
691	}
692	
693	/// Parse the positional arguments. Return the new state and the new positional index.
694	fn parse_positional<'a>(
695	    cmd: &clap::Command,
696	    pos_index: usize,
697	    is_escaped: bool,
698	    state: ParseState<'a>,
699	) -> (ParseState<'a>, usize) {
700	    let pos_arg = cmd
701	        .get_positionals()
702	        .find(|p| p.get_index() == Some(pos_index));
703	    let num_args = pos_arg
704	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
705	        .unwrap_or(1);
706	
707	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
708	        if num_args > 1 {
709	            (ParseState::Pos((pos_index, 1)), pos_index)
710	        } else {
711	            if is_escaped {
712	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
713	            } else {
714	                (ParseState::ValueDone, pos_index + 1)
715	            }
716	        }
717	    };
718	    match state {
719	        ParseState::ValueDone => {
720	            update_state_with_new_positional(pos_index)
721	        },
722	        ParseState::Pos((prev_pos_index, num_arg)) => {
723	            if prev_pos_index == pos_index {
724	                if num_arg + 1 < num_args {
725	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
726	                } else {
727	                    if is_escaped {
728	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
729	                    } else {
730	                        (ParseState::ValueDone, pos_index + 1)
731	                    }
732	                }
733	            } else {
734	                update_state_with_new_positional(pos_index)
735	            }
736	        }
737	        ParseState::Opt(..) => unreachable!(
738	            "This branch won't be hit,
739	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
740	        ),
741	    }
742	}
743	
744	/// Parse optional flag argument. Return new state
745	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
746	    let range = opt.get_num_args().expect("built");
747	    let max = range.max_values();
748	    if count < max {
749	        ParseState::Opt((opt, count + 1))
750	    } else {
751	        ParseState::ValueDone
752	    }
753	}
754	
755	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
756	    cmd.get_positionals()
757	        .find(|a| a.get_index() == Some(pos_index))
758	        .map(|p| p.is_allow_hyphen_values_set())
759	        .unwrap_or(false)
760	}
761	
762	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
763	    let val = arg.to_value_os();
764	    if val.starts_with("-") {
765	        if let ParseState::Opt((opt, _)) = state {
766	            return opt.is_allow_hyphen_values_set();
767	        }
768	    }
769	
770	    false
771	}
