use clap::{Arg, ArgAction, Command};
use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};

fn name_candidates() -> Vec<CompletionCandidate> {
    vec![
        CompletionCandidate::new("alice"),
        CompletionCandidate::new("alina"),
        CompletionCandidate::new("alina"), // duplicate, keep first
        CompletionCandidate::new("bob"),
    ]
}

fn inspect_cmd() -> Command {
    Command::new("inspect")
        .alias("i")
        .arg(Arg::new("name").long("name").add(ArgValueCandidates::new(name_candidates)))
        .arg(Arg::new("format").long("format").value_parser(["json", "yaml"]))
        .arg(Arg::new("query").value_parser(["all", "changed"]))
        .arg(
