                .hide(true)
                .arg(Arg::new("level").value_parser(["on", "off"])),
        )
}

fn tree(multicall: bool) -> Command {
    let mut root = Command::new("tool")
        .subcommand(Command::new("busybox").subcommand(inspect_cmd()))
        .subcommand(inspect_cmd())
        .subcommand(Command::new("status"));
    if multicall { root = root.multicall(true); }
    root
}

fn comp(argv: &[&str], multicall: bool) -> Vec<String> {
    let mut cmd = tree(multicall);
    let arg_index = argv.len() - 1;
    let args = argv.iter().map(|s| s.to_string().into()).collect();
    clap_complete::engine::complete(&mut cmd, args, arg_index, None)
        .unwrap()
        .into_iter()
        .map(|c| c.get_value().to_string_lossy().into_owned())
        .collect()
}

fn show(label: &str, argv: &[&str], mc: bool) {
    println!("{label:55} {:?} => {:?}", argv, comp(argv, mc));
